#!/usr/bin/env node
'use strict';

/**
 * Regenerates the TypeScript copies of the electronics lookup tables kept as data in memory/Electronics:
 *   gerber_file_roles.csv     extension -> board-file role
 *   placement_layers.csv      Pick Place layer name -> board side
 *   package_class_lookup.csv  exact footprint name -> package class and mount type
 * The CSVs are the data. The backend Docker context cannot reach memory/, so, like the feature-graph schemas,
 * each table is generated into src. Never hand-edit a generated file; a spec fails when it drifts.
 * Run from backend/:  npm run electronics:sync-lookups
 */

const fs = require('fs');
const path = require('path');
const { parseCsv } = require('./lib/electronics-memory-format');

const memoryDir = path.resolve(__dirname, '../../memory/Electronics');
const outDir = path.resolve(__dirname, '../src/modules/electronics-costing/domain/lookups');

const TABLES = [
  {
    csv: 'gerber_file_roles.csv',
    out: 'file-roles.generated.ts',
    name: 'FILE_ROLES',
    type: 'FileRole',
    declaration: [
      "export type FileFamily = 'gerber' | 'excellon' | 'report';",
      '',
      'export interface FileRole {',
      '  extension: string;',
      '  role: string;',
      '  family: FileFamily;',
      '  sourceUrl: string;',
      '  sourceDate: string;',
      '}',
    ],
    map: (get) => ({ extension: get('extension'), role: get('role'), family: get('family'), sourceUrl: get('source_url'), sourceDate: get('source_date') }),
  },
  {
    csv: 'placement_layers.csv',
    out: 'placement-layers.generated.ts',
    name: 'PLACEMENT_LAYERS',
    type: 'PlacementLayer',
    declaration: ['export interface PlacementLayer {', '  layerName: string;', "  side: 'top' | 'bottom';", '  sourceUrl: string;', '  sourceDate: string;', '}'],
    map: (get) => ({ layerName: get('layer_name'), side: get('side'), sourceUrl: get('source_url'), sourceDate: get('source_date') }),
  },
  {
    csv: 'package_class_lookup.csv',
    out: 'package-class-lookup.generated.ts',
    name: 'PACKAGE_CLASS_LOOKUP',
    type: 'PackageClassEntry',
    declaration: [
      'export interface PackageClassEntry {',
      '  footprintName: string;',
      '  standard: string;',
      '  packageClass: string | null;',
      "  mountType: 'smd' | 'tht' | 'mark';",
      '  pinCount: number | null;',
      '  sourceUrl: string;',
      '  sourceDate: string;',
      '}',
    ],
    map: (get) => ({
      footprintName: get('footprint_name'),
      standard: get('standard'),
      packageClass: get('package_class') || null,
      mountType: get('mount_type'),
      pinCount: get('pin_count') === '' ? null : Number(get('pin_count')),
      sourceUrl: get('source_url'),
      sourceDate: get('source_date'),
    }),
  },
];

function render(table) {
  const [header, ...rows] = parseCsv(fs.readFileSync(path.join(memoryDir, table.csv), 'utf8'));
  const entries = rows.map((r) => table.map((name) => (r[header.indexOf(name)] ?? '').trim()));
  return [
    `// GENERATED by scripts/sync-electronics-lookups.js from memory/Electronics/${table.csv}. Do not edit.`,
    ...table.declaration,
    '',
    `export const ${table.name}: ReadonlyArray<${table.type}> = ${JSON.stringify(entries, null, 2)} as ReadonlyArray<${table.type}>;`,
    '',
  ].join('\n');
}

if (require.main === module) {
  fs.mkdirSync(outDir, { recursive: true });
  for (const table of TABLES) {
    fs.writeFileSync(path.join(outDir, table.out), render(table));
    console.log(`wrote ${path.relative(process.cwd(), path.join(outDir, table.out))}`);
  }
}

module.exports = { TABLES, render, outDir };
